import React, { useMemo, useCallback, useEffect, useState } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { Marked } from 'marked';
import { gfmHeadingId } from 'marked-gfm-heading-id';
import { mangle } from 'marked-mangle';
import DOMPurify from 'dompurify';
import classNames from 'classnames';
import MarkupTypes from '../utils/MarkupTypes.ts';
import { useExtlinkTarget, useExtlinkIcon } from '../hooks/extlinkTarget.ts';
import ExternalLinkDecorator from './ExternalLinkDecorator.tsx';

type MarkdownProps = {
  data: string,
  className: string,
  markupType: MarkupTypes
}

const sanitizeAndDecorateLinks = (html: string, openInNewTab: boolean, showIcon: boolean): string => {
  const clean = DOMPurify.sanitize(html);
  const template = document.createElement('template');
  template.innerHTML = clean;
  const decoratorMarkup = renderToStaticMarkup(<ExternalLinkDecorator />);
  template.content.querySelectorAll('a[href]').forEach((anchor) => {
    if (/^https?:\/\//i.test(anchor.getAttribute('href') || '')) {
      if (openInNewTab) {
        anchor.setAttribute('target', '_blank');
      }
      if (showIcon && !anchor.querySelector('.externalLinkDecorator')) {
        anchor.insertAdjacentHTML('beforeend', decoratorMarkup);
      }
      anchor.setAttribute('rel', 'noopener noreferrer');
    }
  });
  return template.innerHTML;
};

const Markdown = ({ data, className, markupType, ...otherProps }: MarkdownProps) => {
  const openInNewTab = useExtlinkTarget();
  const showIcon = useExtlinkIcon();
  const marked = useMemo(() => new Marked(), []);
  marked.use(mangle());
  const options = {
    prefix: ''
  };

  marked.use(gfmHeadingId(options));
  const parseData = useCallback(
    (data: any, type: string) => {
      if (!data) {
        return;
      }
      if (type === MarkupTypes.markdown) {
        // Use marked for swagger 1.0 and 2.0
        return sanitizeAndDecorateLinks(marked.parse(data) as string, openInNewTab, showIcon);
      }
      // Use markdown-it (implements commonmark spec)
      // eslint-disable-next-line global-require
      const md = require('markdown-it')('commonmark', { linkify: true }).enable('linkify');
      return sanitizeAndDecorateLinks(md.render(data), openInNewTab, showIcon);
    },
    [marked, openInNewTab, showIcon]
  );
  const [convertedData, updateConvertedData] = useState(() => parseData(data, markupType));

  useEffect(() => {
    updateConvertedData(parseData(data, markupType));
  }, [data, markupType, parseData]);

  return <div className={classNames('markdown', className)} data-testid="markdown" dangerouslySetInnerHTML={{ __html: convertedData as string }} {...otherProps} />;
}

export default Markdown;
