import { useConfig } from '../contexts/config';

/**
 * Whether external links should open in a new tab, driven by the Drupal Extlink setting
 * passed through as config.options.extlinkTarget. Defaults to true when not provided.
 */
export const useExtlinkTarget = (): boolean => {
  const { options }: any = useConfig();
  return options?.extlinkTarget !== false;
};

export const useExtlinkIcon = (): boolean => {
  const { options }: any = useConfig();
  return options?.extlinkClass === 'ext';
};
